"""Render the visually triaged register. Dates remain explicitly unverified."""
import sys as _rs, os as _ro; _rs.path.insert(0, _ro.path.dirname(_ro.path.abspath(__file__))); from reports_dir import REPORTS, SCALPING_BACKTEST  # noqa: E402
from pathlib import Path
import json,collections
root=(REPORTS/'icy-tea/intake')
rows=json.loads((root/'new-source-register.json').read_text(encoding='utf-8'))
summary=json.loads((root/'summary.json').read_text(encoding='utf-8'))
probes=json.loads((root/'dated-reference-results.json').read_text(encoding='utf-8'))
for row in rows:
    probe=next((p for p in probes['results'] if p['sourceId']==row['id']),None)
    row['probe']=None if probe is None else {k:probe.get(k) for k in ['status','candidateDate','window','htfAssumption','error']}
counts=collections.Counter(r['dateStatus'] for r in rows)
body='''<!doctype html><html><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>some_icy_tea · Source library and filter contract</title><style>body{background:#090d14;color:#e5e7eb;font:15px system-ui;margin:0;padding:24px}main{max-width:1550px;margin:auto}a{color:#7dd3fc}h1{color:#facc15}section,article{background:#121a27;border:1px solid #334155;border-radius:12px;padding:18px;margin:16px 0}table{border-collapse:collapse;width:100%}td,th{padding:12px;text-align:left;border-bottom:1px solid #334155}#gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:16px}#gallery article{margin:0}img{width:100%;max-height:560px;object-fit:contain;background:white}input,select{padding:12px;color:white;background:#172033;border:1px solid #475569;border-radius:8px}small{color:#94a3b8}details{margin-top:10px}li{margin:8px 0}.held{color:#fbbf24}</style><main><h1>some_icy_tea · Source library & filter contract</h1>'''
body+=f'<p>{summary["files"]} folder files · {summary["newFiles"]} added files · {len(rows)} unique new images · {summary["duplicateFiles"]} exact duplicates. All 385 unique still images have checkpointed OCR; all 349 new unique charts were visually triaged.</p>'
body+='<p><a href="../reconstruction.html">Previous reconstruction</a> · <a href="/?tab=market-structure-shift">Open MSS workspace</a> · <a href="new-source-register.json">Source register JSON</a></p>'
body+=f'<section><h2>Evidence boundary</h2><p class="held">{counts["DATE_NOT_SHOWN"]} charts omit a complete date; {counts["PARTIAL_DATE_YEAR_FROM_PUBLICATION_UNVERIFIED"]} have day/month/weekday with a publication-year candidate; one shows an explicit 2023 date. These are not candle-verified dates. Publication time is not entry time.</p><p>Colours and arrows describe annotated trades. They do not prove an executable historical signal or that every condition was known at entry. This inventory does not certify exact entries, stops, targets or outcomes.</p></section>'
models=[('SWEEP_REVERSAL','Liquidity → shift → retest','HTF context; sweep/reclaim; selected shift; valid-array retest; structural stop and liquidity target.'),('UNICORN','Unicorn','Entry inside an active, already-known breaker/FVG overlap. Two checked types are insufficient.'),('INVERSION','Inversion / balanced range','IFVG close-through and BPR opposing-gap overlap retain separate activation clocks.'),('CONTINUATION','Post-shift continuation','Later arrays until reversal-extreme breach or HTF invalidation; does not certify the full MMXM narrative.'),('THREE_DRIVES','Three drives','Three confirmed progressively extended pivots. Hand-drawn peaks can differ from library pivots.')]
body+='<section><h2>Reusable playbooks</h2><table><tr><th>Playbook</th><th>Independent requirements</th></tr>'
for key,name,rule in models:body+=f'<tr><td><a href="/?tab=market-structure-shift&amp;playbook={key}">{name}</a></td><td>{rule}</td></tr>'
body+='</table><p>Array kinds use OR; required evidence uses AND. Native close/wick CHOCH, local swing break and CISD remain distinct.</p></section>'
body+='''<section><h2>Controls and chart interpretation</h2><ul><li>HTF levels project onto TF2. Each activation and confirmation must precede entry.</li><li>Displacement: optional numeric body test, labelled local interpretation; native CHOCH unchanged.</li><li>Premium / discount and 62–79% OTE: explicitly measured TF2 formation range. Weekly / HTF dealing ranges and FVG quadrants remain distinct.</li><li>CE entry waits for the actual midpoint retest; edge entries can occur earlier.</li><li>Sessions use explicit New York clock windows and timezone conversion. Screenshot-specific timing still needs verification.</li><li>Stops and targets: structural sweep stop and known, unswept opposing liquidity. PD-array edges and standard-deviation projections are different target policies.</li><li>Required SMT/news remain unverified without synchronized comparison candles / an event calendar.</li><li>Rejection, mitigation and propulsion blocks, opening/weekend gaps, session highs/lows and HTF quadrants are retained as source features; complete detectors are not implemented by these common filters.</li><li>NQ/ES futures cannot be replaced with QQQ/SPY. Contract and price source must match.</li></ul></section>'''
probe_counts=collections.Counter(p['status'] for p in probes['results'])
body+=f'<section><h2>Dated window probes</h2><p>{len(probes["results"])} approximate windows checked: {probe_counts["NATIVE_CANDIDATE_IN_APPROXIMATE_WINDOW"]} with native candidates, {probe_counts["NO_NATIVE_ENTRY_IN_WINDOW"]} without native entries, {probe_counts["FUTURES_CONTRACT_NOT_MAPPED"]} with an unmapped futures contract.</p><p>These use printed dates with inferred years where flagged, approximate chart windows, and an assumed HTF where the image omits it. A candidate is not an exact reproduction; a missing native entry does not disprove a different annotated model.</p><p><a href="dated-reference-probes.json">Probe selections</a> · <a href="dated-reference-results.json">Candle and candidate evidence</a> · <a href="aapl-filter-regression.json">AAPL native regression</a></p></section>'
body+='<section><h2>Browse source charts</h2><input id="search" aria-label="Search source annotations" placeholder="Symbol, BPR, SMT, date…"><select id="symbol" aria-label="Source symbol"><option value="">All symbols</option>'+''.join(f'<option>{s}</option>' for s in sorted({s for r in rows for s in r['symbolLabels']}))+'</select> <span id="count"></span></section><div id="gallery"></div>'
body+='<script>const rows='+json.dumps(rows,ensure_ascii=True).replace('<','\\u003c')+''';const gallery=document.querySelector('#gallery');const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function render(){const q=document.querySelector('#search').value.toLowerCase(),symbol=document.querySelector('#symbol').value;const chosen=rows.filter(r=>(!symbol||r.symbolLabels.includes(symbol))&&JSON.stringify([r.symbolLabels,r.familyHints,r.annotations,r.candidateDate,r.id]).toLowerCase().includes(q));document.querySelector('#count').textContent=chosen.length+' sources';gallery.innerHTML=chosen.map(r=>`<article><h3>#${r.newIndex} · ${escape(r.symbolLabels.join(' / ')||'Symbol not labelled')} · drawn ${r.visualDirection}</h3><a href="${r.preview}" target="_blank"><img loading="lazy" src="${r.preview}" alt="Source chart ${r.newIndex}"></a><p>${escape(r.familyHints.join(' · ')||'Model unresolved')}</p><small>${escape(r.dateStatus)} ${escape(r.candidateDate||'')}</small><p>${escape(r.sourceFeatures.join(' · '))}</p><p class="held">${escape(r.probe ? r.probe.status+' · '+r.probe.candidateDate+' · '+r.probe.window.join('–') : 'Exact candle reproduction not verified')}</p><details><summary>Source labels & verification boundary</summary><ul>${r.annotations.map(t=>`<li>${escape(t)}</li>`).join('')}</ul><p>${escape(r.verification)}</p><code>${r.sha256}</code></details></article>`).join('')}document.querySelector('#search').addEventListener('input',render);document.querySelector('#symbol').addEventListener('change',render);render();</script></main></html>'''
(root/'index.html').write_text(body,encoding='utf-8')
print('Rendered',len(rows),'source cards')
